#include <stdio.h>
#include <stdbool.h>

int main(void) {
    int K, N;
    if (scanf("%d %d", &K, &N) != 2) {
        return 0;
    }

    char alphabet[100];
    char message[1005];

    scanf("%s", alphabet);
    scanf("%s", message);

    bool in_alphabet[256] = {false};
    for (int i = 0; alphabet[i] != '\0'; i++) {
        in_alphabet[(unsigned char)alphabet[i]] = true;
    }

    bool possible = true;
    for (int i = 0; message[i] != '\0'; i++) {
        if (!in_alphabet[(unsigned char)message[i]]) {
            possible = false;
            break;
        }
    }

    if (possible) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    return 0;
}
